import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} param0
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate is a real date in YYYY-MM-DD format
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== issueDate) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    const discountPercent = line.discountPercent ?? 0;
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product by SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a line item (qty times unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ ok: true, value: { subtotal: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || typeof invoice !== 'object' || !Array.isArray(invoice.lines)) {
    return fail('INVALID_INVOICE');
  }

  let subtotal = 0;
  for (const line of invoice.lines) {
    if (!line || typeof line !== 'object' || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
      return fail('INVALID_LINE');
    }
    subtotal += lineTotal(line);
  }

  const total = subtotal;
  return ok({ subtotal, total });
}

/**
 * Add a line to an invoice. If the SKU already exists, increase its quantity.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} param1
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get product by SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = [];
  let found = false;

  for (const line of invoice.lines) {
    if (line.sku === sku) {
      newLines.push({
        ...line,
        qty: line.qty + qty,
      });
      found = true;
    } else {
      newLines.push({ ...line });
    }
  }

  // If SKU not found, add new line
  if (!found) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if it would remove the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without that line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already in use
 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  const number = numberResult.value;

  // Create new invoice with number and status 'issued'
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

